-- =============================================================================
-- 10-adif_schema.sql -- the ADIF reference tier (PostgreSQL, PG-1 database `ionis`)
-- GENERATED by scripts/adif_tier.py from ADIF's published all.json for 3.1.6, 3.1.7. Do not edit by hand: regenerate.
-- Every key carries adif_version: versions coexist and a new release is additive.
-- Enumeration rows are keyed by ADIF's own record key; `record` keeps each exactly as published.
-- =============================================================================

CREATE SCHEMA IF NOT EXISTS adif;

CREATE TABLE IF NOT EXISTS adif.release (
    adif_version  text PRIMARY KEY,
    status        text NOT NULL,
    released      timestamptz,
    created       timestamptz,
    source_url    text NOT NULL,
    source_sha256 text NOT NULL,
    loaded_at     timestamptz NOT NULL DEFAULT now()
);

-- The lab-wide CURRENT ADIF version (spec: one pointer; rows pin at write and re-pin only
-- by explicit migration). One row, enforced. Loading a version never moves it: set it
-- deliberately with `adif_tier.py set-current --version X`.
CREATE TABLE IF NOT EXISTS adif.current (
    singleton     boolean PRIMARY KEY DEFAULT TRUE CHECK (singleton),
    adif_version  text NOT NULL REFERENCES adif.release (adif_version),
    set_at        timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS adif.datatype (
    adif_version text NOT NULL REFERENCES adif.release (adif_version),
    data_type_name                           text,
    data_type_indicator                      text,
    description                              text,
    minimum_value                            text,
    maximum_value                            text,
    import_only                              boolean,
    comments                                 text,
    record       jsonb NOT NULL,
    PRIMARY KEY (adif_version, data_type_name)
);

CREATE TABLE IF NOT EXISTS adif.field (
    adif_version text NOT NULL REFERENCES adif.release (adif_version),
    field_name                               text,
    data_type                                text,
    enumeration                              text,
    description                              text,
    header_field                             boolean,
    minimum_value                            text,
    maximum_value                            text,
    import_only                              boolean,
    comments                                 text,
    record       jsonb NOT NULL,
    PRIMARY KEY (adif_version, field_name)
);
-- No foreign key on data_type: CREDIT_GRANTED / CREDIT_SUBMITTED name two types
-- ('CreditList,AwardList'). The load checks every listed type instead (see load_sql).

-- ARRL_Section
CREATE TABLE IF NOT EXISTS adif.arrl_section (
    adif_version text NOT NULL REFERENCES adif.release (adif_version),
    record_key   text NOT NULL,
    abbreviation                             text,
    section_name                             text,
    dxcc_entity_code                         text,
    from_date                                timestamptz,
    deleted_date                             timestamptz,
    import_only                              boolean,
    comments                                 text,
    record       jsonb NOT NULL,
    PRIMARY KEY (adif_version, record_key)
);
CREATE UNIQUE INDEX IF NOT EXISTS arrl_section_natural ON adif.arrl_section (adif_version, abbreviation);
-- ARRL_Section: dxcc_entity_code holds lists in some rows (e.g. '43,202'); text, no foreign key.

