-- Cross-references ADIF itself defines. A load that violates one fails whole.
ALTER TABLE adif.primary_administrative_subdivision DROP CONSTRAINT IF EXISTS primary_administrative_subdivision_dxcc_entity_code_fk;
ALTER TABLE adif.primary_administrative_subdivision ADD CONSTRAINT primary_administrative_subdivision_dxcc_entity_code_fk FOREIGN KEY (adif_version, dxcc_entity_code) REFERENCES adif.dxcc_entity_code (adif_version, entity_code);
ALTER TABLE adif.region DROP CONSTRAINT IF EXISTS region_dxcc_entity_code_fk;
ALTER TABLE adif.region ADD CONSTRAINT region_dxcc_entity_code_fk FOREIGN KEY (adif_version, dxcc_entity_code) REFERENCES adif.dxcc_entity_code (adif_version, entity_code);
ALTER TABLE adif.secondary_administrative_subdivision DROP CONSTRAINT IF EXISTS secondary_administrative_subdivision_dxcc_entity_code_fk;
ALTER TABLE adif.secondary_administrative_subdivision ADD CONSTRAINT secondary_administrative_subdivision_dxcc_entity_code_fk FOREIGN KEY (adif_version, dxcc_entity_code) REFERENCES adif.dxcc_entity_code (adif_version, entity_code);
ALTER TABLE adif.secondary_administrative_subdivision_alt DROP CONSTRAINT IF EXISTS secondary_administrative_subdivision_alt_dxcc_entity_code_fk;
ALTER TABLE adif.secondary_administrative_subdivision_alt ADD CONSTRAINT secondary_administrative_subdivision_alt_dxcc_entity_code_fk FOREIGN KEY (adif_version, dxcc_entity_code) REFERENCES adif.dxcc_entity_code (adif_version, entity_code);
ALTER TABLE adif.submode DROP CONSTRAINT IF EXISTS submode_mode_fk;
ALTER TABLE adif.submode ADD CONSTRAINT submode_mode_fk FOREIGN KEY (adif_version, mode) REFERENCES adif.mode (adif_version, mode);

-- The read-only role sees everything in this schema, now and later.
DO $$ BEGIN IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'ionis_ro') THEN
  GRANT USAGE ON SCHEMA adif TO ionis_ro;
  GRANT SELECT ON ALL TABLES IN SCHEMA adif TO ionis_ro;
  ALTER DEFAULT PRIVILEGES IN SCHEMA adif GRANT SELECT ON TABLES TO ionis_ro;
END IF; END $$;
